package com.rh.contollers;

import com.rh.models.Departement;
import com.rh.models.Employe;
import com.rh.services.EmployeService;
import javafx.fxml.FXML;
import javafx.fxml.FXMLLoader;
import javafx.fxml.Initializable;
import javafx.geometry.Insets;
import javafx.scene.Parent;
import javafx.scene.Scene;
import javafx.scene.control.*;
import javafx.scene.layout.FlowPane;
import javafx.scene.layout.HBox;
import javafx.scene.layout.VBox;
import javafx.stage.Stage;

import java.net.URL;
import java.util.ResourceBundle;

public class EmployeController implements Initializable {

    // Liste (employe.fxml)
    @FXML private FlowPane cardsContainer;
    @FXML private Button btnAdd;

    // Formulaire (employe_form.fxml)
    @FXML private Label lblMatricule;
    @FXML private ToggleButton tbSitCelib, tbSitMarie, tbSitDivorce, tbSitVeuf;
    @FXML private TextField tfNom, tfPrenom, tfCIN, tfTelephone, tfCNSS;
    @FXML private DatePicker dpNaissance;
    @FXML private ToggleButton tbDeptB2B, tbDeptB2C, tbDeptBureau;
    @FXML private TextField tfProfil, tfSalaire, tfRIB;
    @FXML private DatePicker dpEmbauche;
    @FXML private ToggleButton tbContratCDI, tbContratCDD, tbContratStage;
    @FXML private ToggleButton tbStatutActif, tbStatutInactif;
    @FXML private ComboBox<String> cbBanque;
    @FXML private Label errNom, errCIN, errTelephone;
    @FXML private Button btnCancel, btnSaveAndAdd, btnCreate;

    private final EmployeService service = new EmployeService();
    private Employe editing = null;

    @Override
    public void initialize(URL location, ResourceBundle resources) {
        if (cardsContainer != null) {
            refreshCards();
            btnAdd.setOnAction(e -> openAddForm());
        }
        if (btnCreate != null) {
            initializeForm();
        }
    }

    private void initializeForm() {
        ToggleGroup sitFam = new ToggleGroup();
        tbSitCelib.setToggleGroup(sitFam);
        tbSitMarie.setToggleGroup(sitFam);
        tbSitDivorce.setToggleGroup(sitFam);
        tbSitVeuf.setToggleGroup(sitFam);

        ToggleGroup dept = new ToggleGroup();
        tbDeptB2B.setToggleGroup(dept);
        tbDeptB2C.setToggleGroup(dept);
        tbDeptBureau.setToggleGroup(dept);
        tbDeptB2B.setUserData(Departement.CENTRE_APPEL_B2B);
        tbDeptB2C.setUserData(Departement.CENTRE_APPEL_B2C);
        tbDeptBureau.setUserData(Departement.BUREAU_ETUDE);

        ToggleGroup contrat = new ToggleGroup();
        tbContratCDI.setToggleGroup(contrat);
        tbContratCDD.setToggleGroup(contrat);
        tbContratStage.setToggleGroup(contrat);

        ToggleGroup statut = new ToggleGroup();
        tbStatutActif.setToggleGroup(statut);
        tbStatutInactif.setToggleGroup(statut);

        int lastId = service.getAll().stream().mapToInt(Employe::getId).max().orElse(0);
        lblMatricule.setText("EMP-0" + (lastId + 1));
        tbSitCelib.setSelected(true);
        tbStatutActif.setSelected(true);

        btnCancel.setOnAction(e -> closeForm());
        btnCreate.setOnAction(e -> handleSave(false));
        btnSaveAndAdd.setOnAction(e -> handleSave(true));
    }

    public void setEmploye(Employe e) {
        editing = e;
        if (e == null) return;
        lblMatricule.setText("EMP-0" + e.getId());
        tfNom.setText(e.getNom());
        tfPrenom.setText(e.getPrenom());
        dpNaissance.setValue(e.getDateNaissance());
        tfCIN.setText(e.getCin());
        tfTelephone.setText(e.getTelephone());
        tfCNSS.setText(e.getnCNSS());
        tfProfil.setText(e.getProfil());
        dpEmbauche.setValue(e.getDateEmbauche());
        tfSalaire.setText(String.valueOf(e.getSalaireMensuelNet()));
        tfRIB.setText(e.getnRIB());
        if (e.getDepartement() != null) {
            switch (e.getDepartement()) {
                case CENTRE_APPEL_B2B: tbDeptB2B.setSelected(true); break;
                case CENTRE_APPEL_B2C: tbDeptB2C.setSelected(true); break;
                case BUREAU_ETUDE: tbDeptBureau.setSelected(true); break;
            }
        }
    }

    private void handleSave(boolean addAnother) {
        clearErrors();
        if (!validateFields()) return;

        Employe e = editing != null ? editing : new Employe();
        e.setNom(tfNom.getText().trim());
        e.setPrenom(tfPrenom.getText().trim());
        e.setDateNaissance(dpNaissance.getValue());
        e.setSituationFamiliale(getSit());
        e.setCin(tfCIN.getText().trim());
        e.setTelephone(tfTelephone.getText().trim());
        e.setnCNSS(tfCNSS.getText().trim());

        ToggleButton d = getDept();
        if (d != null && d.getUserData() instanceof Departement) {
            e.setDepartement((Departement) d.getUserData());
        }

        e.setProfil(tfProfil.getText().trim());
        e.setDateEmbauche(dpEmbauche.getValue());
        try { e.setSalaireMensuelNet(Double.parseDouble(tfSalaire.getText().trim())); }
        catch (Exception ex) { e.setSalaireMensuelNet(0); }
        e.setTypeContrat(getContrat());
        e.setStatut(getStatut());
        e.setnRIB(tfRIB.getText().trim());

        if (editing == null) service.add(e); else service.update(e);
        if (cardsContainer != null) refreshCards();
        if (addAnother) resetForm(); else closeForm();
    }

    private String getSit() {
        if (tbSitCelib.isSelected()) return tbSitCelib.getText();
        if (tbSitMarie.isSelected()) return tbSitMarie.getText();
        if (tbSitDivorce.isSelected()) return tbSitDivorce.getText();
        if (tbSitVeuf.isSelected()) return tbSitVeuf.getText();
        return null;
    }

    private ToggleButton getDept() {
        if (tbDeptB2B.isSelected()) return tbDeptB2B;
        if (tbDeptB2C.isSelected()) return tbDeptB2C;
        if (tbDeptBureau.isSelected()) return tbDeptBureau;
        return null;
    }

    private String getContrat() {
        if (tbContratCDI.isSelected()) return tbContratCDI.getText();
        if (tbContratCDD.isSelected()) return tbContratCDD.getText();
        if (tbContratStage.isSelected()) return tbContratStage.getText();
        return null;
    }

    private String getStatut() {
        if (tbStatutActif.isSelected()) return tbStatutActif.getText();
        if (tbStatutInactif.isSelected()) return tbStatutInactif.getText();
        return null;
    }

    private boolean validateFields() {
        boolean ok = true;
        if (tfNom.getText() == null || tfNom.getText().trim().isEmpty()) {
            errNom.setText("Nom obligatoire"); tfNom.getStyleClass().add("field-error"); ok = false;
        }
        if (tfCIN.getText() == null || !tfCIN.getText().trim().matches("\\d{8}")) {
            errCIN.setText("8 chiffres"); tfCIN.getStyleClass().add("field-error"); ok = false;
        }
        if (tfTelephone.getText() == null || tfTelephone.getText().trim().isEmpty()) {
            errTelephone.setText("Requis"); tfTelephone.getStyleClass().add("field-error"); ok = false;
        }
        if (getDept() == null) { tbDeptB2B.getStyleClass().add("field-error"); ok = false; }
        if (dpEmbauche.getValue() == null) { dpEmbauche.getStyleClass().add("field-error"); ok = false; }
        return ok;
    }

    private void clearErrors() {
        errNom.setText(""); errCIN.setText(""); errTelephone.setText("");
        tfNom.getStyleClass().removeAll("field-error");
        tfCIN.getStyleClass().removeAll("field-error");
        tfTelephone.getStyleClass().removeAll("field-error");
        tbDeptB2B.getStyleClass().removeAll("field-error");
        dpEmbauche.getStyleClass().removeAll("field-error");
    }

    private void resetForm() {
        editing = null;
        tfNom.clear(); tfPrenom.clear(); dpNaissance.setValue(null); tfCIN.clear(); tfTelephone.clear(); tfCNSS.clear();
        tbSitCelib.setSelected(true);
        tbDeptB2B.setSelected(false); tbDeptB2C.setSelected(false); tbDeptBureau.setSelected(false);
        tfProfil.clear(); dpEmbauche.setValue(null); tfSalaire.clear();
        tbContratCDI.setSelected(false); tbContratCDD.setSelected(false); tbContratStage.setSelected(false);
        tfRIB.clear(); cbBanque.setValue(null);
        int lastId = service.getAll().stream().mapToInt(Employe::getId).max().orElse(0);
        lblMatricule.setText("EMP-0" + (lastId + 1));
    }

    private void closeForm() {
        Stage stage = (Stage) btnCancel.getScene().getWindow();
        stage.close();
    }

    public void refreshCards() {
        if (cardsContainer == null) return;
        cardsContainer.getChildren().clear();
        int idx = 0;
        for (Employe emp : service.getAll()) {
            VBox card = new VBox(6);
            card.setPadding(new Insets(10));
            card.getStyleClass().addAll("employee-card", "employee-color-" + (idx % 4 + 1));

            HBox h = new HBox(8);
            Label name = new Label(emp.getNom() + " " + emp.getPrenom());
            name.getStyleClass().add("employee-name");
            Label d = new Label(emp.getDepartement() != null ? emp.getDepartement().toString() : "");
            d.getStyleClass().add("employee-dept");
            h.getChildren().addAll(name, d);

            Button btn = new Button("Voir détails");
            btn.getStyleClass().add("btn-link");
            btn.setOnAction(evt -> openDetails(emp));

            card.getChildren().addAll(h,
                new Label("Profil: " + (emp.getProfil() != null ? emp.getProfil() : "-")),
                new Label("Tel: " + (emp.getTelephone() != null ? emp.getTelephone() : "-")),
                new Label(String.format("Salaire: %.2f DH", emp.getSalaireMensuelNet())),
                btn);

            cardsContainer.getChildren().add(card);
            idx++;
        }
    }

    private void openAddForm() {
        try {
            FXMLLoader loader = new FXMLLoader(getClass().getResource("/com/rh/views/employe_form.fxml"));
            Parent root = loader.load();
            Stage stage = new Stage();
            stage.setTitle("Ajouter un employé");
            stage.setScene(new Scene(root));
            stage.initOwner(cardsContainer.getScene().getWindow());
            stage.initModality(javafx.stage.Modality.APPLICATION_MODAL);
            stage.showAndWait();
        } catch (Exception ex) {
            ex.printStackTrace();
        }
    }

    private void openDetails(Employe emp) {
        try {
            FXMLLoader loader = new FXMLLoader(getClass().getResource("/com/rh/views/employe_detail.fxml"));
            Parent root = loader.load();
            EmployeDetailController controller = loader.getController();
            controller.setEmploye(emp);
            controller.setParent(this);
            Stage stage = new Stage();
            stage.setTitle("Détails employé");
            stage.setScene(new Scene(root));
            stage.initOwner(cardsContainer.getScene().getWindow());
            stage.initModality(javafx.stage.Modality.APPLICATION_MODAL);
            stage.showAndWait();
        } catch (Exception ex) {
            ex.printStackTrace();
        }
    }
}

package com.rh.contollers;

import com.rh.models.Employe;
import com.rh.services.EmployeService;
import javafx.fxml.FXML;
import javafx.fxml.Initializable;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.stage.Stage;

import java.net.URL;
import java.util.ResourceBundle;

public class EmployeDetailController implements Initializable {

    @FXML private Label lblName;
    @FXML private Label lblDept;
    @FXML private Label lblProfil;
    @FXML private Label lblTel;
    @FXML private Label lblSalaire;
    @FXML private Label lblDateEmbauche;
    @FXML private Button btnEdit;
    @FXML private Button btnDelete;
    @FXML private Button btnClose;

    private EmployeService service = new EmployeService();
    private Employe employe;
    private EmployeController parent;

    public void setEmploye(Employe e) {
        this.employe = e;
        populate();
    }

    public void setParent(EmployeController parent) { this.parent = parent; }

    @Override
    public void initialize(URL location, ResourceBundle resources) {
        btnClose.setOnAction(e -> close());

        btnDelete.setOnAction(e -> {
            if (employe != null) {
                service.delete(employe);
                if (parent != null) parent.refreshCards();
                close();
            }
        });

        btnEdit.setOnAction(e -> {
            try {
                javafx.fxml.FXMLLoader loader = new javafx.fxml.FXMLLoader(getClass().getResource("/com/rh/views/employe_form.fxml"));
                javafx.scene.Parent root = loader.load();
                EmployeFormController controller = loader.getController();
                controller.setParent(parent);
                controller.setEmploye(employe);

                Stage stage = new Stage();
                stage.setTitle("Modifier un employé");
                stage.setScene(new javafx.scene.Scene(root));
                stage.initOwner(btnEdit.getScene().getWindow());
                stage.initModality(javafx.stage.Modality.APPLICATION_MODAL);
                stage.showAndWait();
                // refresh after edit
                if (parent != null) parent.refreshCards();
                close();
            } catch (Exception ex) {
                ex.printStackTrace();
            }
        });
    }

    private void populate() {
        if (employe == null) return;
        lblName.setText(employe.getNom() + " " + employe.getPrenom());
        lblDept.setText("Département: " + (employe.getDepartement() != null ? employe.getDepartement().toString() : "-"));
        lblProfil.setText("Profil: " + (employe.getProfil() != null ? employe.getProfil() : "-"));
        lblTel.setText("Tel: " + (employe.getTelephone() != null ? employe.getTelephone() : "-"));
        lblSalaire.setText(String.format("Salaire: %.2f DH", employe.getSalaireMensuelNet()));
        lblDateEmbauche.setText("Embauché le: " + (employe.getDateEmbauche() != null ? employe.getDateEmbauche().toString() : "-"));
    }

    private void close() {
        Stage stage = (Stage) btnClose.getScene().getWindow();
        stage.close();
    }
}

package com.rh.contollers;

import com.rh.models.Departement;
import com.rh.models.Employe;
import com.rh.services.EmployeService;
import javafx.fxml.FXML;
import javafx.fxml.Initializable;
import javafx.scene.control.*;
import javafx.stage.Stage;

import java.net.URL;
import java.time.LocalDate;
import java.util.ResourceBundle;

public class EmployeFormController implements Initializable {

    @FXML private TextField tfNom;
    @FXML private TextField tfPrenom;
    @FXML private DatePicker dpNaissance;
    @FXML private ChoiceBox<Departement> cbDepartement;
    @FXML private TextField tfProfil;
    @FXML private TextField tfTelephone;
    @FXML private TextField tfSalaire;
    @FXML private Button btnSave;
    @FXML private Button btnCancel;

    private final EmployeService service = new EmployeService();
    private EmployeController parent;
    private Employe editing;

    public void setParent(EmployeController parent) {
        this.parent = parent;
    }

    public void setEmploye(Employe e) {
        this.editing = e;
        if (e == null) return;
        tfNom.setText(e.getNom());
        tfPrenom.setText(e.getPrenom());
        dpNaissance.setValue(e.getDateNaissance());
        cbDepartement.setValue(e.getDepartement());
        tfProfil.setText(e.getProfil());
        tfTelephone.setText(e.getTelephone());
        tfSalaire.setText(String.valueOf(e.getSalaireMensuelNet()));
    }

    @Override
    public void initialize(URL location, ResourceBundle resources) {
        cbDepartement.getItems().setAll(Departement.values());

        btnCancel.setOnAction(e -> close());

        btnSave.setOnAction(e -> {
            if (editing == null) {
                Employe emp = new Employe();
                emp.setNom(tfNom.getText());
                emp.setPrenom(tfPrenom.getText());
                emp.setDateNaissance(dpNaissance.getValue());
                emp.setDepartement(cbDepartement.getValue());
                emp.setProfil(tfProfil.getText());
                emp.setTelephone(tfTelephone.getText());
                try {
                    emp.setSalaireMensuelNet(Double.parseDouble(tfSalaire.getText()));
                } catch (NumberFormatException ex) {
                    emp.setSalaireMensuelNet(0);
                }
                service.add(emp);
            } else {
                editing.setNom(tfNom.getText());
                editing.setPrenom(tfPrenom.getText());
                editing.setDateNaissance(dpNaissance.getValue());
                editing.setDepartement(cbDepartement.getValue());
                editing.setProfil(tfProfil.getText());
                editing.setTelephone(tfTelephone.getText());
                try {
                    editing.setSalaireMensuelNet(Double.parseDouble(tfSalaire.getText()));
                } catch (NumberFormatException ex) {
                    editing.setSalaireMensuelNet(0);
                }
                service.update(editing);
            }
            if (parent != null) parent.refreshCards();
            close();
        });
    }

    private void close() {
        Stage stage = (Stage) btnCancel.getScene().getWindow();
        stage.close();
    }
}

package com.rh.contollers;

import com.rh.models.Departement;
import com.rh.models.Employe;
import com.rh.services.EmployeService;
import javafx.fxml.FXML;
import javafx.fxml.Initializable;
import javafx.scene.control.*;
import javafx.scene.control.ToggleButton;
import javafx.stage.Stage;

import java.net.URL;
import java.time.LocalDate;
import java.util.ResourceBundle;

public class EmployesController implements Initializable {

    @FXML private Label lblMatricule;

    // Situation familiale
    @FXML private ToggleButton tbSitCelib;
    @FXML private ToggleButton tbSitMarie;
    @FXML private ToggleButton tbSitDivorce;
    @FXML private ToggleButton tbSitVeuf;

    // Personal
    @FXML private TextField tfNom;
    @FXML private TextField tfPrenom;
    @FXML private DatePicker dpNaissance;
    @FXML private TextField tfCIN;
    @FXML private TextField tfTelephone;
    @FXML private TextField tfCNSS;

    // Professionnel
    @FXML private ToggleButton tbDeptB2B;
    @FXML private ToggleButton tbDeptB2C;
    @FXML private ToggleButton tbDeptBureau;
    @FXML private TextField tfProfil;
    @FXML private DatePicker dpEmbauche;
    @FXML private TextField tfSalaire;
    @FXML private ToggleButton tbContratCDI;
    @FXML private ToggleButton tbContratCDD;
    @FXML private ToggleButton tbContratStage;
    @FXML private ToggleButton tbStatutActif;
    @FXML private ToggleButton tbStatutInactif;

    // Bancaire
    @FXML private TextField tfRIB;
    @FXML private ComboBox<String> cbBanque;

    // Errors
    @FXML private Label errNom;
    @FXML private Label errCIN;
    @FXML private Label errTelephone;

    @FXML private Button btnCancel;
    @FXML private Button btnSaveAndAdd;
    @FXML private Button btnCreate;

    private final EmployeService service = new EmployeService();
    private Employe editing = null;
    private com.rh.contollers.EmployeController parent;

    @Override
    public void initialize(URL location, ResourceBundle resources) {
        // Toggle groups
        ToggleGroup sitFamGroup = new ToggleGroup();
        tbSitCelib.setToggleGroup(sitFamGroup);
        tbSitMarie.setToggleGroup(sitFamGroup);
        tbSitDivorce.setToggleGroup(sitFamGroup);
        tbSitVeuf.setToggleGroup(sitFamGroup);

        ToggleGroup deptGroup = new ToggleGroup();
        tbDeptB2B.setToggleGroup(deptGroup);
        tbDeptB2C.setToggleGroup(deptGroup);
        tbDeptBureau.setToggleGroup(deptGroup);
        tbDeptB2B.setUserData(Departement.CENTRE_APPEL_B2B);
        tbDeptB2C.setUserData(Departement.CENTRE_APPEL_B2C);
        tbDeptBureau.setUserData(Departement.BUREAU_ETUDE);

        ToggleGroup contratGroup = new ToggleGroup();
        tbContratCDI.setToggleGroup(contratGroup);
        tbContratCDD.setToggleGroup(contratGroup);
        tbContratStage.setToggleGroup(contratGroup);

        ToggleGroup statutGroup = new ToggleGroup();
        tbStatutActif.setToggleGroup(statutGroup);
        tbStatutInactif.setToggleGroup(statutGroup);

        // generate matricule based on last id
        int lastId = service.getAll().stream().mapToInt(Employe::getId).max().orElse(0);
        lblMatricule.setText("EMP-0" + (lastId + 1));

        // default selections
        tbSitCelib.setSelected(true);
        tbStatutActif.setSelected(true);

        // button actions
        btnCancel.setOnAction(e -> close());

        btnCreate.setOnAction(e -> handleSave(false));
        btnSaveAndAdd.setOnAction(e -> handleSave(true));
    }

    public void setEmploye(Employe e) {
        this.editing = e;
        if (e == null) return;
        lblMatricule.setText("EMP-0" + e.getId());
        tfNom.setText(e.getNom());
        tfPrenom.setText(e.getPrenom());
        dpNaissance.setValue(e.getDateNaissance());
        tfCIN.setText(e.getCin());
        tfTelephone.setText(e.getTelephone());
        tfCNSS.setText(e.getnCNSS());
        tfProfil.setText(e.getProfil());
        dpEmbauche.setValue(e.getDateEmbauche());
        tfSalaire.setText(String.valueOf(e.getSalaireMensuelNet()));
        tfRIB.setText(e.getnRIB());
        cbBanque.setValue(null);
        if (e.getDepartement() != null) {
            switch (e.getDepartement()) {
                case CENTRE_APPEL_B2B: tbDeptB2B.setSelected(true); break;
                case CENTRE_APPEL_B2C: tbDeptB2C.setSelected(true); break;
                case BUREAU_ETUDE: tbDeptBureau.setSelected(true); break;
            }
        }
    }

    public void setParent(com.rh.contollers.EmployeController parent) {
        this.parent = parent;
    }

    private void handleSave(boolean addAnother) {
        clearErrors();
        boolean ok = validateFields();
        if (!ok) return;

        Employe e = editing != null ? editing : new Employe();
        e.setNom(tfNom.getText().trim());
        e.setPrenom(tfPrenom.getText().trim());
        e.setDateNaissance(dpNaissance.getValue());
        ToggleButton sit = (ToggleButton) (tbSitCelib.isSelected() ? tbSitCelib : tbSitMarie.isSelected() ? tbSitMarie : tbSitDivorce.isSelected() ? tbSitDivorce : tbSitVeuf);
        e.setSituationFamiliale(sit != null ? sit.getText() : null);
        e.setCin(tfCIN.getText().trim());
        e.setTelephone(tfTelephone.getText().trim());
        e.setnCNSS(tfCNSS.getText().trim());

        ToggleButton dept = (ToggleButton) (tbDeptB2B.isSelected() ? tbDeptB2B : tbDeptB2C.isSelected() ? tbDeptB2C : tbDeptBureau.isSelected() ? tbDeptBureau : null);
        if (dept != null && dept.getUserData() instanceof Departement) e.setDepartement((Departement) dept.getUserData());

        e.setProfil(tfProfil.getText().trim());
        e.setDateEmbauche(dpEmbauche.getValue());
        try { e.setSalaireMensuelNet(Double.parseDouble(tfSalaire.getText().trim())); } catch (Exception ex) { e.setSalaireMensuelNet(0); }

        ToggleButton contrat = (ToggleButton) (tbContratCDI.isSelected() ? tbContratCDI : tbContratCDD.isSelected() ? tbContratCDD : tbContratStage.isSelected() ? tbContratStage : null);
        e.setTypeContrat(contrat != null ? contrat.getText() : null);
        ToggleButton statut = (ToggleButton) (tbStatutActif.isSelected() ? tbStatutActif : tbStatutInactif.isSelected() ? tbStatutInactif : null);
        e.setStatut(statut != null ? statut.getText() : null);

        e.setnRIB(tfRIB.getText().trim());
        e.setnCNSS(tfCNSS.getText().trim());

        if (editing == null) {
            service.add(e);
        } else {
            service.update(e);
        }

        if (parent != null) parent.refreshCards();

        if (addAnother) {
            resetForm();
        } else {
            close();
        }
    }

    private boolean validateFields() {
        boolean ok = true;
        if (tfNom.getText() == null || tfNom.getText().trim().isEmpty()) {
            errNom.setText("Le nom est obligatoire"); ok = false; tfNom.getStyleClass().add("field-error");
        }
        if (tfCIN.getText() == null || !tfCIN.getText().trim().matches("\\d{8}")) {
            errCIN.setText("CIN doit contenir 8 chiffres"); ok = false; tfCIN.getStyleClass().add("field-error");
        }
        if (tfTelephone.getText() == null || tfTelephone.getText().trim().isEmpty()) {
            errTelephone.setText("Téléphone requis"); ok = false; tfTelephone.getStyleClass().add("field-error");
        }
        if (!(tbDeptB2B.isSelected() || tbDeptB2C.isSelected() || tbDeptBureau.isSelected())) {
            // show a dialog or set style on dept toggles
            tbDeptB2B.getStyleClass().add("field-error"); ok = false;
        }
        if (dpEmbauche.getValue() == null) { dpEmbauche.getStyleClass().add("field-error"); ok = false; }
        return ok;
    }

    private void clearErrors() {
        errNom.setText(""); errCIN.setText(""); errTelephone.setText("");
        tfNom.getStyleClass().removeAll("field-error");
        tfCIN.getStyleClass().removeAll("field-error");
        tfTelephone.getStyleClass().removeAll("field-error");
        tbDeptB2B.getStyleClass().removeAll("field-error");
        dpEmbauche.getStyleClass().removeAll("field-error");
    }

    private void resetForm() {
        editing = null;
        tfNom.clear(); tfPrenom.clear(); dpNaissance.setValue(null); tfCIN.clear(); tfTelephone.clear(); tfCNSS.clear();
        tbSitCelib.setSelected(true); tbDeptB2B.setSelected(false); tbDeptB2C.setSelected(false); tbDeptBureau.setSelected(false);
        tfProfil.clear(); dpEmbauche.setValue(null); tfSalaire.clear(); tbContratCDI.setSelected(false); tbContratCDD.setSelected(false); tbContratStage.setSelected(false);
        tfRIB.clear(); cbBanque.setValue(null);
        int lastId = service.getAll().stream().mapToInt(Employe::getId).max().orElse(0);
        lblMatricule.setText("EMP-0" + (lastId + 1));
    }

    private void close() {
        Stage stage = (Stage) btnCancel.getScene().getWindow();
        stage.close();
    }
}

package com.rh.models;

public enum Departement {
