}

package com.rh.models;

import java.time.LocalDate;
import java.util.Objects;
import com.rh.models.Departement;

public class Employe {
    private int id;
    private String nom;
    private String prenom;
    private LocalDate dateNaissance;
    private String situationFamiliale;
    private String cin;
    private String telephone;
    private double salaireMensuelNet;
    private String profil;
    private String typeContrat;
    private String statut;
    private LocalDate dateEmbauche;
    private String nRIB;
    private String nCNSS;
    private Departement departement;

    public Employe() {
    }

    public Employe(int id, String nom, String prenom, LocalDate dateNaissance, String situationFamiliale,
                   String cin, String telephone, double salaireMensuelNet, String profil, String typeContrat,
                   String statut, LocalDate dateEmbauche, String nRIB, String nCNSS, Departement departement) {
        this.id = id;
        this.nom = nom;
        this.prenom = prenom;
        this.dateNaissance = dateNaissance;
        this.situationFamiliale = situationFamiliale;
        this.cin = cin;
        this.telephone = telephone;
        this.salaireMensuelNet = salaireMensuelNet;
        this.profil = profil;
        this.typeContrat = typeContrat;
        this.statut = statut;
        this.dateEmbauche = dateEmbauche;
        this.nRIB = nRIB;
        this.nCNSS = nCNSS;
        this.departement = departement;
    }

    public int getId() {
        return id;
    }

    public void setId(int id) {
        this.id = id;
    }

    public String getNom() {
        return nom;
    }

    public void setNom(String nom) {
        this.nom = nom;
    }

    public String getPrenom() {
        return prenom;
    }

    public void setPrenom(String prenom) {
        this.prenom = prenom;
    }

    public LocalDate getDateNaissance() {
        return dateNaissance;
    }

    public void setDateNaissance(LocalDate dateNaissance) {
        this.dateNaissance = dateNaissance;
    }

    public String getSituationFamiliale() {
        return situationFamiliale;
    }

    public void setSituationFamiliale(String situationFamiliale) {
        this.situationFamiliale = situationFamiliale;
    }

    public String getCin() {
        return cin;
    }

    public void setCin(String cin) {
        this.cin = cin;
    }

    public String getTelephone() {
        return telephone;
    }

    public void setTelephone(String telephone) {
        this.telephone = telephone;
    }

    public double getSalaireMensuelNet() {
        return salaireMensuelNet;
    }

    public void setSalaireMensuelNet(double salaireMensuelNet) {
        this.salaireMensuelNet = salaireMensuelNet;
    }

    public String getProfil() {
        return profil;
    }

    public void setProfil(String profil) {
        this.profil = profil;
    }

    public String getTypeContrat() {
        return typeContrat;
    }

    public void setTypeContrat(String typeContrat) {
        this.typeContrat = typeContrat;
    }

    public String getStatut() {
        return statut;
    }

    public void setStatut(String statut) {
        this.statut = statut;
    }

    public LocalDate getDateEmbauche() {
        return dateEmbauche;
    }

    public void setDateEmbauche(LocalDate dateEmbauche) {
        this.dateEmbauche = dateEmbauche;
    }

    public String getnRIB() {
        return nRIB;
    }

    public void setnRIB(String nRIB) {
        this.nRIB = nRIB;
    }

    public String getnCNSS() {
        return nCNSS;
    }

    public void setnCNSS(String nCNSS) {
        this.nCNSS = nCNSS;
    }

    public Departement getDepartement() {
        return departement;
    }

    public void setDepartement(Departement departement) {
        this.departement = departement;
    }

    @Override
    public String toString() {
        return "Employe{" +
                "id=" + id +
                ", nom='" + nom + '\'' +
                ", prenom='" + prenom + '\'' +
                ", dateNaissance=" + dateNaissance +
                ", situationFamiliale='" + situationFamiliale + '\'' +
                ", cin='" + cin + '\'' +
                ", telephone='" + telephone + '\'' +
                ", salaireMensuelNet=" + salaireMensuelNet +
                ", profil='" + profil + '\'' +
                ", typeContrat='" + typeContrat + '\'' +
                ", statut='" + statut + '\'' +
                ", dateEmbauche=" + dateEmbauche +
                ", nRIB='" + nRIB + '\'' +
                ", nCNSS='" + nCNSS + '\'' +
                ", departement=" + departement +
                '}';
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        Employe employe = (Employe) o;
        return id == employe.id;
    }

    @Override
    public int hashCode() {
        return Objects.hash(id);
    }
}

package com.rh.services;

import com.rh.interfaces.IServices;
import com.rh.models.Departement;
import com.rh.models.Employe;
import com.rh.utils.IsobatDB;

import java.sql.*;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;

public class EmployeService implements IServices<Employe> {

    private final Connection cnx;

    public EmployeService() {
        this.cnx = IsobatDB.getInstance().getCnx();
    }

    @Override
    public void add(Employe e) {
        String sql = "INSERT INTO employe (nom, prenom, dateNaissance, situationFamiliale, cin, telephone, salaireMensuelNet, profil, typeContrat, statut, dateEmbauche, nRIB, nCNSS, departement) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)";
        try (PreparedStatement ps = cnx.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
            ps.setString(1, e.getNom());
            ps.setString(2, e.getPrenom());
            ps.setDate(3, e.getDateNaissance() != null ? Date.valueOf(e.getDateNaissance()) : null);
            ps.setString(4, e.getSituationFamiliale());
            ps.setString(5, e.getCin());
            ps.setString(6, e.getTelephone());
            ps.setDouble(7, e.getSalaireMensuelNet());
            ps.setString(8, e.getProfil());
            ps.setString(9, e.getTypeContrat());
            ps.setString(10, e.getStatut());
            ps.setDate(11, e.getDateEmbauche() != null ? Date.valueOf(e.getDateEmbauche()) : null);
            ps.setString(12, e.getnRIB());
            ps.setString(13, e.getnCNSS());
            ps.setString(14, e.getDepartement() != null ? e.getDepartement().name() : null);
            ps.executeUpdate();
            try (ResultSet rs = ps.getGeneratedKeys()) {
                if (rs.next()) {
                    e.setId(rs.getInt(1));
                }
            }
        } catch (SQLException ex) {
            ex.printStackTrace();
        }
    }

    @Override
    public List<Employe> getAll() {
        List<Employe> list = new ArrayList<>();
        String sql = "SELECT * FROM employe";
        try (Statement st = cnx.createStatement(); ResultSet rs = st.executeQuery(sql)) {
            while (rs.next()) {
                Employe e = mapResultSet(rs);
                list.add(e);
            }
        } catch (SQLException ex) {
            ex.printStackTrace();
        }
        return list;
    }

    @Override
    public void update(Employe e) {
        String sql = "UPDATE employe SET nom=?, prenom=?, dateNaissance=?, situationFamiliale=?, cin=?, telephone=?, salaireMensuelNet=?, profil=?, typeContrat=?, statut=?, dateEmbauche=?, nRIB=?, nCNSS=?, departement=? WHERE id=?";
        try (PreparedStatement ps = cnx.prepareStatement(sql)) {
            ps.setString(1, e.getNom());
            ps.setString(2, e.getPrenom());
            ps.setDate(3, e.getDateNaissance() != null ? Date.valueOf(e.getDateNaissance()) : null);
            ps.setString(4, e.getSituationFamiliale());
            ps.setString(5, e.getCin());
            ps.setString(6, e.getTelephone());
            ps.setDouble(7, e.getSalaireMensuelNet());
            ps.setString(8, e.getProfil());
            ps.setString(9, e.getTypeContrat());
            ps.setString(10, e.getStatut());
            ps.setDate(11, e.getDateEmbauche() != null ? Date.valueOf(e.getDateEmbauche()) : null);
            ps.setString(12, e.getnRIB());
            ps.setString(13, e.getnCNSS());
            ps.setString(14, e.getDepartement() != null ? e.getDepartement().name() : null);
            ps.setInt(15, e.getId());
            ps.executeUpdate();
        } catch (SQLException ex) {
            ex.printStackTrace();
        }
    }

    @Override
    public void delete(Employe e) {
        String sql = "DELETE FROM employe WHERE id=?";
        try (PreparedStatement ps = cnx.prepareStatement(sql)) {
            ps.setInt(1, e.getId());
            ps.executeUpdate();
        } catch (SQLException ex) {
            ex.printStackTrace();
        }
    }

    public Employe findById(int id) {
        String sql = "SELECT * FROM employe WHERE id=?";
        try (PreparedStatement ps = cnx.prepareStatement(sql)) {
            ps.setInt(1, id);
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    return mapResultSet(rs);
                }
            }
        } catch (SQLException ex) {
            ex.printStackTrace();
        }
        return null;
    }

    private Employe mapResultSet(ResultSet rs) throws SQLException {
        Employe e = new Employe();
        e.setId(rs.getInt("id"));
        e.setNom(rs.getString("nom"));
        e.setPrenom(rs.getString("prenom"));
        Date dNaiss = rs.getDate("dateNaissance");
        if (dNaiss != null) e.setDateNaissance(dNaiss.toLocalDate());
        e.setSituationFamiliale(rs.getString("situationFamiliale"));
        e.setCin(rs.getString("cin"));
        e.setTelephone(rs.getString("telephone"));
        e.setSalaireMensuelNet(rs.getDouble("salaireMensuelNet"));
        e.setProfil(rs.getString("profil"));
        e.setTypeContrat(rs.getString("typeContrat"));
        e.setStatut(rs.getString("statut"));
        Date dEmbauche = rs.getDate("dateEmbauche");
        if (dEmbauche != null) e.setDateEmbauche(dEmbauche.toLocalDate());
        e.setnRIB(rs.getString("nRIB"));
        e.setnCNSS(rs.getString("nCNSS"));
        String dep = rs.getString("departement");
        if (dep != null) {
            try {
                e.setDepartement(Departement.valueOf(dep));
            } catch (IllegalArgumentException ex) {
                // try matching by label
                for (Departement d : Departement.values()) {
                    if (d.toString().equalsIgnoreCase(dep)) {
                        e.setDepartement(d);
                        break;
                    }
                }
            }
        }
        return e;
    }
}

