    -fx-background-color: #F0E6DA;
}

/* ════════════════════════════════════
   SIDEBAR
   ════════════════════════════════════ */
.sidebar {
    -fx-background-color: #75070C;
    -fx-min-width: 245px;
    -fx-max-width: 245px;
}

.logo-box {
    -fx-background-color: #5C0509;
    -fx-padding: 18 14 18 14;
}

.logo-icon-circle {
    -fx-font-size: 26px;
    -fx-text-fill: #FFFFFF;
    -fx-background-color: rgba(255,255,255,0.15);
    -fx-background-radius: 50px;
    -fx-padding: 8 11 8 11;
    -fx-font-weight: bold;
}

.logo-title {
    -fx-font-size: 21px;
    -fx-font-weight: bold;
    -fx-text-fill: #FFFFFF;
}

.logo-sub {
    -fx-font-size: 7.5px;
    -fx-text-fill: rgba(255,255,255,0.55);
    -fx-letter-spacing: 1.2px;
}

/* Container nav avec padding horizontal pour l'effet de marges */
.nav-container {
    -fx-padding: 10 10 10 10;
    -fx-background-color: transparent;
}

.sidebar-sep {
    -fx-background-color: rgba(255,255,255,0.18);
    -fx-border-color: rgba(255,255,255,0.18);
    -fx-padding: 0 10 0 10;
}

.sidebar-btn {
    -fx-background-color: transparent;
    -fx-text-fill: rgba(255,255,255,0.80);
    -fx-font-size: 13.5px;
    -fx-alignment: CENTER_LEFT;
    -fx-padding: 11 14 11 14;
    -fx-cursor: hand;
    -fx-border-color: transparent;
    -fx-background-radius: 8;
    -fx-border-radius: 8;
    -fx-pref-height: 44px;
}

.sidebar-btn:hover {
    -fx-background-color: rgba(255,255,255,0.12);
    -fx-text-fill: #FFFFFF;
}

.sidebar-btn-active {
    -fx-background-color: #4F6815;
    -fx-text-fill: #FFFFFF;
    -fx-font-weight: bold;
    -fx-background-radius: 8;
}

.sidebar-btn-active:hover {
    -fx-background-color: #3E5210;
}

/* Bouton Déconnexion */
.sidebar-btn-logout {
    -fx-background-color: transparent;
    -fx-text-fill: rgba(255,255,255,0.70);
    -fx-font-size: 13px;
    -fx-alignment: CENTER_LEFT;
    -fx-padding: 13 20 13 20;
    -fx-cursor: hand;
    -fx-border-color: transparent;
    -fx-background-radius: 0;
    -fx-pref-height: 48px;
}

.sidebar-btn-logout:hover {
    -fx-background-color: rgba(255,255,255,0.10);
    -fx-text-fill: #FFFFFF;
}

.sidebar-user {
    -fx-padding: 14 18 18 18;
    -fx-background-color: #5C0509;
}

.user-name {
    -fx-text-fill: #FFFFFF;
    -fx-font-size: 13px;
    -fx-font-weight: bold;
}

.user-role {
    -fx-text-fill: rgba(255,255,255,0.60);
    -fx-font-size: 11px;
}

/* ════════════════════════════════════
   HEADER
   ════════════════════════════════════ */
.header {
    -fx-background-color: #FFFFFF;
    -fx-padding: 14 24 14 24;
    -fx-effect: dropshadow(gaussian, rgba(0,0,0,0.07), 10, 0, 0, 3);
    -fx-border-color: #F0E6DA;
    -fx-border-width: 0 0 1 0;
}

.header-title {
    -fx-font-size: 20px;
    -fx-font-weight: bold;
    -fx-text-fill: #1A1A1A;
}

.search-box {
    -fx-background-color: #F5F5F5;
    -fx-background-radius: 20px;
    -fx-border-color: #E0D8D0;
    -fx-border-radius: 20px;
    -fx-border-width: 1;
    -fx-padding: 6 14 6 14;
}

.search-field {
    -fx-background-color: transparent;
    -fx-border-color: transparent;
    -fx-font-size: 13px;
    -fx-text-fill: #333;
    -fx-prompt-text-fill: #aaa;
}

.notif-badge {
    -fx-background-color: #75070C;
    -fx-text-fill: white;
    -fx-font-size: 8px;
    -fx-font-weight: bold;
    -fx-background-radius: 20px;
    -fx-padding: 1 4 1 4;
    -fx-translate-x: 6;
    -fx-translate-y: -4;
}

.avatar-circle {
    -fx-background-color: #4F6815;
    -fx-background-radius: 50px;
    -fx-text-fill: white;
    -fx-font-size: 14px;
    -fx-font-weight: bold;
    -fx-padding: 8 12 8 12;
    -fx-cursor: hand;
}

/* ════════════════════════════════════
   DASHBOARD CONTENT
   ════════════════════════════════════ */
.content-scroll {
    -fx-background: #F0E6DA;
    -fx-background-color: #F0E6DA;
    -fx-border-color: transparent;
}

.content-scroll > .viewport {
    -fx-background-color: #F0E6DA;
}

.dashboard-root {
    -fx-background-color: #F0E6DA;
    -fx-padding: 24 28 28 28;
}

/* Welcome bar */
.welcome-label {
    -fx-font-size: 16px;
    -fx-font-weight: bold;
    -fx-text-fill: #1A1A1A;
}

.date-label {
    -fx-font-size: 12px;
    -fx-text-fill: #888;
    -fx-background-color: white;
    -fx-background-radius: 8px;
    -fx-padding: 5 12 5 12;
    -fx-border-color: #E8DDD4;
    -fx-border-radius: 8px;
    -fx-border-width: 1;
}

/* ── KPI Cards ───────────────────────────────────────── */
.stat-card {
    -fx-background-color: #FFFFFF;
    -fx-background-radius: 14px;
    -fx-border-color: #EDE4D8;
    -fx-border-radius: 14px;
    -fx-border-width: 1;
    -fx-padding: 20 22 20 22;
    -fx-effect: dropshadow(gaussian, rgba(0,0,0,0.07), 12, 0, 0, 3);
}

.card-label {
    -fx-font-size: 12px;
    -fx-text-fill: #888888;
    -fx-font-weight: normal;
}

.card-value {
    -fx-font-size: 30px;
    -fx-font-weight: bold;
    -fx-text-fill: #1A1A1A;
}

.card-icon {
    -fx-font-size: 22px;
    -fx-background-radius: 10px;
    -fx-padding: 10 12 10 12;
}

.card-icon-olive {
    -fx-background-color: #e8f0d8;
}

.card-icon-cherry {
    -fx-background-color: #fde8e9;
}

.card-icon-butter {
    -fx-background-color: #fff8e1;
}

.trend-positive {
    -fx-text-fill: #4F6815;
    -fx-font-size: 11.5px;
    -fx-font-weight: bold;
}

.trend-negative {
    -fx-text-fill: #75070C;
    -fx-font-size: 11.5px;
    -fx-font-weight: bold;
}

/* ── Chart Cards ─────────────────────────────────────── */
.chart-card {
    -fx-background-color: #FFFFFF;
    -fx-background-radius: 14px;
    -fx-border-color: #EDE4D8;
    -fx-border-radius: 14px;
    -fx-border-width: 1;
    -fx-padding: 20 22 20 22;
    -fx-effect: dropshadow(gaussian, rgba(0,0,0,0.07), 12, 0, 0, 3);
}

.section-title {
    -fx-font-size: 14.5px;
    -fx-font-weight: bold;
    -fx-text-fill: #1A1A1A;
}

/* ── Bar Chart colors ────────────────────────────────── */
.default-color0.chart-bar { -fx-bar-fill: #4F6815; }
.default-color1.chart-bar { -fx-bar-fill: #75070C; }

.chart-plot-background {
    -fx-background-color: #fafafa;
}

.chart-vertical-grid-lines {
    -fx-stroke: transparent;
}

.chart-horizontal-grid-lines {
    -fx-stroke: #eeeeee;
}

/* ── Pie Chart colors ────────────────────────────────── */
.default-color0.chart-pie { -fx-pie-color: #4F6815; }
.default-color1.chart-pie { -fx-pie-color: #75070C; }
.default-color2.chart-pie { -fx-pie-color: #FFEDAB; }
.default-color3.chart-pie { -fx-pie-color: #8aad4a; }
.default-color4.chart-pie { -fx-pie-color: #c8a96e; }

/* ── Table ───────────────────────────────────────────── */
.activity-table {
    -fx-background-color: transparent;
    -fx-border-color: #EDE4D8;
    -fx-border-radius: 8px;
    -fx-background-radius: 8px;
}

.activity-table .column-header-background {
    -fx-background-color: #F5F0EA;
    -fx-background-radius: 6px 6px 0 0;
}

.activity-table .column-header .label {
    -fx-font-weight: bold;
    -fx-font-size: 12px;
    -fx-text-fill: #4F6815;
}

.activity-table .table-row-cell {
    -fx-background-color: white;
    -fx-border-color: transparent transparent #F5F0EA transparent;
}

.activity-table .table-row-cell:odd {
    -fx-background-color: #fdfaf7;
}

.activity-table .table-row-cell:selected {
    -fx-background-color: #e8f0d8;
    -fx-text-fill: #1A1A1A;
}

.activity-table .table-cell {
    -fx-font-size: 12.5px;
    -fx-text-fill: #333333;
    -fx-padding: 8 10 8 10;
}

/* ── Misc buttons ────────────────────────────────────── */
.btn-link {
    -fx-background-color: transparent;
    -fx-text-fill: #4F6815;
    -fx-font-size: 12.5px;
    -fx-cursor: hand;
    -fx-border-color: transparent;
    -fx-font-weight: bold;
}

.btn-link:hover {
    -fx-text-fill: #75070C;
    -fx-underline: true;
}


/* ── Employee cards ───────────────────────────────────── */
.employee-card {
    -fx-background-color: #FFFFFF;
    -fx-background-radius: 10px;
    -fx-border-color: #EDE4D8;
    -fx-border-radius: 10px;
    -fx-border-width: 1;
    -fx-padding: 12 14 12 14;
    -fx-pref-width: 220px;
    -fx-effect: dropshadow(gaussian, rgba(0,0,0,0.06), 8, 0, 0, 2);
}

.employee-name {
    -fx-font-size: 13px;
    -fx-font-weight: bold;
    -fx-text-fill: #1A1A1A;
}

.employee-dept {
    -fx-font-size: 11px;
    -fx-text-fill: #6b6b6b;
}

/* colored variants */
.employee-color-1 { -fx-border-color: #E8F5E9; }
.employee-color-2 { -fx-border-color: #FFF3E0; }
.employee-color-3 { -fx-border-color: #EDE7F6; }
.employee-color-4 { -fx-border-color: #E3F2FD; }

.employee-card:hover {
    -fx-translate-y: -4px;
    -fx-effect: dropshadow(gaussian, rgba(0,0,0,0.12), 12, 0, 0, 6);
}

/* Form helpers requested */
.section-title-label {
    -fx-font-family: "Poppins";
    -fx-font-size: 10px;
    -fx-font-weight: bold;
    -fx-text-fill: #75070C;
}
.auto-id-badge {
    -fx-background-color: #FFF0F0;
    -fx-border-color: #F5C0C0;
    -fx-border-radius: 6px;
    -fx-background-radius: 6px;
    -fx-border-width: 1px;
    -fx-font-family: "Poppins";
    -fx-font-size: 12px;
    -fx-text-fill: #75070C;
    -fx-font-weight: bold;
    -fx-padding: 6 10 6 10;
}
.field-error {
    -fx-border-color: #75070C ;
    -fx-border-width: 1.5px ;
    -fx-border-radius: 6px ;
}

/* Toggle styles (basic) */
.toggle-dept {
    -fx-background-color: #FFFFFF;
    -fx-border-color: #E0D0BE;
    -fx-border-radius: 8px;
    -fx-background-radius: 8px;
    -fx-border-width: 1.5px;
    -fx-font-family: "Poppins";
    -fx-font-size: 12px;
    -fx-text-fill: #555555;
    -fx-cursor: hand;
    -fx-padding: 10 16 10 16;
}
.toggle-dept:selected {
    -fx-background-color: #75070C;
    -fx-border-color: #75070C;
    -fx-text-fill: #FFFFFF;
    -fx-font-weight: bold;
}
.toggle-contrat {
    -fx-background-color: #FFFFFF;
    -fx-border-color: #E0D0BE;
    -fx-border-radius: 8px;
    -fx-background-radius: 8px;
    -fx-border-width: 1.5px;
    -fx-font-family: "Poppins";
    -fx-font-size: 12px;
    -fx-text-fill: #555555;
    -fx-cursor: hand;
    -fx-padding: 8 20 8 20;
}
.toggle-contrat:selected {
    -fx-background-color: #4F6815;
    -fx-border-color: #4F6815;
    -fx-text-fill: #FFFFFF;
    -fx-font-weight: bold;
}
